import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { expect, within } from 'storybook/test';
import { MemoryRouter } from 'react-router-dom';
import { MultiSiteProvider } from '@salesforce/retail-react-app/app/contexts';
import { Box } from '@salesforce/retail-react-app/app/components/shared/ui';
import { ZimmCartEmptyState } from '.';

const meta: Meta<typeof ZimmCartEmptyState> = {
  title: 'Commerce/ZimmCartEmptyState',
  component: ZimmCartEmptyState,
  parameters: { layout: 'padded' },
  // ZimmCartEmptyState renders the base SFCC `Link` (via its Button as={Link} CTA), which calls
  // useMultiSite().buildUrl unconditionally -- same provider shape zimmCartItemActions/index.stories.tsx
  // and footer/index.stories.tsx already use for the same reason. Identity buildUrl here (AU,
  // this codebase's default site) since this story isn't the one asserting on prefixing --
  // see AtNonAuSite below for that.
  decorators: [
    (Story) => (
      <MemoryRouter>
        <MultiSiteProvider
          site={{ id: 'ZimmermannAU', alias: 'au' }}
          locale={{ id: 'en-AU', alias: 'en-AU' }}
          buildUrl={(path: string) => path}
        >
          <Story />
        </MultiSiteProvider>
      </MemoryRouter>
    ),
  ],
};

export default meta;

type Story = StoryObj<typeof ZimmCartEmptyState>;

export const Default: Story = {};

/**
 * SFCC-11 plan step 4.5 pass criterion 3: "CTA uses the base SFCC Link, and a test at a non-AU
 * site asserts the href carries the site prefix." Overrides the meta-level MultiSiteProvider with
 * a non-AU site and a non-identity `buildUrl` (matching the exact `/en-GB${path}` shape
 * `recentlyViewed/index.test.tsx` and `recentlyViewedFullHistoryCard.test.ts` already use for the
 * identical proof) so the assertion below fails if this component stopped passing its href
 * through the base `Link`'s own multi-site prefixing.
 */
export const AtNonAuSite: Story = {
  decorators: [
    (Story) => (
      <MultiSiteProvider
        site={{ id: 'ZimmermannUK', alias: 'uk' }}
        locale={{ id: 'en-GB', alias: 'en-GB' }}
        buildUrl={(path: string) => `/en-GB${path}`}
      >
        <Story />
      </MultiSiteProvider>
    ),
  ],
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const cta = canvas.getByRole('link', { name: 'Continue Shopping' });
    await expect(cta).toHaveAttribute('href', '/en-GB/');
  },
};

// Reproduces ZimmCartDrawer's own desktop-breakpoint `body` grid declaration verbatim
// (zimmCartDrawer.css.ts's `baseStyle.body[DESKTOP_UP]`: display grid, 22.5rem/26.875rem tracks,
// 140px gap) so this story can prove ZimmCartEmptyState's own gridColumn span against a real
// two-column grid parent -- without importing/nesting the real ZimmCartDrawer itself, which does
// not yet render this component at zero items at all (see zimmCartEmptyState.css.ts's own
// docblock: that wiring is step 4.6's job). This is a *shape-alike* harness for verifying the
// span mechanism in isolation, not a claim that it exercises ZimmCartDrawer's actual code.
//
// `width` is the load-bearing addition over a first draft of this harness (caught live, not
// assumed): a plain block `Box` with no explicit width stretches to its own parent's width (here,
// the Storybook canvas -- ~1408px at a 1440px viewport), which is NOT what the real
// `ZimmCartDrawer` body actually measures. That component's own fixed panel width is 1186px
// (plan.md step B1's own math: 128 + 360 + 140 + 430 + 128 = 1186, fixed in commit 3/step 1.1),
// so its content box -- after the same 128px `paddingInline` gutter each side
// (`var(--zimm-scale-6xl)`, confirmed 128px in `foundation/spacing.ts`) -- is exactly
// 1186 - 128 - 128 = 930px: precisely the sum of the two column tracks plus the gap
// (360 + 140 + 430 = 930). Left unconstrained, the first draft of this story's own `play`
// function failed by comparing this component's width against the harness's own (wrongly wide)
// 1408px instead of the real 930px the drawer would actually offer it -- a bug in the harness,
// not in the recipe (`getComputedStyle` already showed `gridColumn: '1 / -1'` resolving
// correctly even before this fix). Constraining the harness to the real content-box width is
// what makes this story an honest stand-in for the real drawer body.
const GRID_HARNESS_STYLE = {
  display: 'grid',
  gridTemplateColumns: '22.5rem 26.875rem',
  columnGap: 'var(--zimm-scale-3500)',
  width: '58.125rem', // 930px = 22.5rem + 26.875rem + 8.75rem(140px gap) -- see comment above
} as const;

/**
 * Live proof for pass criterion 4 ("Two-to-one column collapse asserted") alongside
 * `zimmCartEmptyState.css.test.ts`'s own object-level assertion -- that file proves the recipe
 * *declares* `gridColumn: '1 / -1'` at the desktop breakpoint; this story proves it actually
 * *takes effect* against a real two-column CSS Grid parent, live-rendered in a real browser
 * engine (Vitest's jsdom cannot evaluate this: no real `@media` cascade, and
 * `getBoundingClientRect` always returns zeros there -- see that test file's own docblock).
 *
 * Requires an actual wide (>= the 1280px desktop breakpoint) viewport to mean anything -- this
 * repo has no `.storybook` viewport-addon preset configured and no `test-storybook` script (both
 * checked before writing this), so this story was verified with an explicit wide viewport driven
 * directly against a live Storybook dev server for this step's own report, rather than relying on
 * a CI-wired check. The `play` function below still runs (and still means something) any time
 * this story is opened in a browser window at or above that width, including the default desktop
 * width Storybook's own UI opens at on a normal developer machine.
 */
export const SpansBothDrawerColumnsAtDesktop: Story = {
  decorators: [
    (Story) => (
      <Box sx={GRID_HARNESS_STYLE} data-testid="grid-harness">
        <Story />
      </Box>
    ),
  ],
  play: async ({ canvasElement }) => {
    if (window.innerWidth < 1280) {
      // Documented, not silently skipped -- see this story's own docblock for why this repo has
      // no way to force a wide viewport for every context this play could run in. Deliberate,
      // narrow diagnostic (Storybook developer tooling, not app code) -- conventions.md's
      // no-console rule targets console.log/console.error, not console.warn.
      console.warn('SpansBothDrawerColumnsAtDesktop: viewport is below 1280px, skipping the span assertion.');
      return;
    }
    const canvas = within(canvasElement);
    const harness = canvas.getByTestId('grid-harness');
    const root = canvas.getByTestId('zimm-cart-empty-state');
    const harnessWidth = harness.getBoundingClientRect().width;
    const rootWidth = root.getBoundingClientRect().width;
    const itemsColumnWidthPx = 22.5 * 16; // 22.5rem items-only track, at a 16px root font size

    // Full-width (spans both tracks), not confined to the 360px items column alone.
    await expect(rootWidth).toBeGreaterThan(itemsColumnWidthPx);
    await expect(Math.round(rootWidth)).toBe(Math.round(harnessWidth));
  },
};

import React from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';
import { Center, Stack, Text, Button } from '@salesforce/retail-react-app/app/components/shared/ui';
import Link from '@salesforce/retail-react-app/app/components/link';

const ZIMM_CART_EMPTY_STATE_RECIPE = 'ZimmCartEmptyState';

const messages = defineMessages({
  // Deliberately generic -- see this file's own "Placeholder body" note below for why the real
  // Figma copy (a specific AU phone number, AU opening hours, and a support email) is not shipped
  // here. Echoes the real copy's own opening phrase ("If you'd like some help...") since that
  // sentence starter carries no region-specific detail of its own to get wrong.
  body: {
    id: 'zimm_cart_empty_state.body',
    defaultMessage: "If you'd like some help, please get in touch with our Client Services team.",
  },
  continueShopping: {
    id: 'zimm_cart_empty_state.cta.continue_shopping',
    defaultMessage: 'Continue Shopping',
  },
});

/**
 * Organism -- SFCC-272 AC2 ("removing the last item shows the empty state 'as per SFCC-277'") /
 * SFCC-11 plan step 4.5. A **discrete, swappable placeholder** for the cart drawer's empty-bag
 * body: SFCC-277 (a separate, not-yet-groomed card, out of this epic's 7-card bundle) owns the
 * real content and replaces this file's contents wholesale -- building it as its own component
 * rather than inline JSX in `ZimmCartDrawer` is what makes that a swap in one file
 * (`.claude/session-notes.md` §4 SFCC-272 decision "AC2 (empty state...): ... Build it as a
 * discrete component, not inline JSX in the drawer, so 277 is a swap in one file").
 *
 * **No heading in this component.** "YOUR BAG IS EMPTY" is SFCC-315 AC2's own, already-shipped
 * header text (`zimmCartDrawer/index.tsx`'s `title = itemCount === 0 ? 'YOUR BAG IS EMPTY' : ...`,
 * rendered by `ZimmDrawer`'s own title slot) -- session-notes.md §11.7 confirms this split
 * explicitly ("'YOUR BAG IS EMPTY' is in the header, not the body"). This component is body-only.
 *
 * **Structure from the `recentlyViewed/index.tsx` precedent** (`EmptyRecentlyViewed`, itself a
 * disclosed, undesigned port of base SFCC's `EmptyCart`,
 * `node_modules/@salesforce/retail-react-app/app/pages/cart/partials/empty-cart.jsx`):
 * `Box > Center > Stack`, a `Button as={Link}` CTA using the **base SFCC `Link`** (not
 * `ZimmLink` -- so the href gets this storefront's real multi-site prefixing via
 * `use-multi-site.js`'s `buildUrl`, called internally by that `Link`), `useIntl` called directly
 * in this leaf under the Context-backed exception `.claude/rules/components.md` > Composition
 * documents for `useIntl`/`useUiCopy` specifically. Visuals (colour/type/spacing tokens) come from
 * SFCC-315's EMPTY BAG Figma nodes (session-notes.md §11.7) instead of that precedent's own
 * autonomous token choices -- that file's own docblock discloses those as an unbacked judgement
 * call made with no design at all; this state has one.
 *
 * **The CTA button is a structural decision from the precedent, not a Figma- or AC-sourced
 * requirement -- disclosed, not silently assumed.** Checked directly before building:
 * `~/Dev/zimmerMANN-skills/.runs/SFCC-11/figma-reference/empty-bag.md` (live Figma pull, all
 * three breakpoints) states plainly "there is no 'continue shopping' / 'browse' button or any
 * call-to-action in this Figma state at all," and flags checking SFCC-272's actual AC text before
 * assuming one is expected. That AC text (session-notes.md line 421-422, pulled from
 * `customfield_10231`) reads only "removing the last item shows the empty state 'as per
 * SFCC-277'" -- no CTA of any kind. The CTA renders here anyway because `plan.md` step 4.5's own
 * "Changes" text mandates taking **structure** from the `recentlyViewed`/`EmptyCart` precedent
 * regardless of what the literal Figma mockup omits (a shopper needs a way out of an empty
 * drawer) -- a plan-level call, not something either source document asked for on its own.
 *
 * **No `isRegistered` branching -- checked, not assumed.** The precedent's own body copy and CTA
 * set both branch on `isRegistered` (a guest additionally sees "Sign In," matching base
 * `EmptyCart`'s identical split). Before copying that here, checked: session-notes.md §11.7 (the
 * real Figma content list for this exact state) names exactly one body message with no
 * guest/registered variant; §11.9/§11.10 (the design-issues and resolved-items lists) raise the
 * hardcoded-AU-contact-details question but never an auth-state question; the actual SFCC-272 AC
 * text above says nothing about auth state either (the empty-state AC is a single sentence
 * deferring entirely to SFCC-277). With no source anywhere calling for a split, and the body
 * itself already a generic placeholder standing in for SFCC-277's real copy, adding an invented
 * `isRegistered` branch on top would be a second layer of invention with nothing backing it --
 * so this component takes no props at all and renders one body message and one CTA regardless of
 * auth state. Flagged here for Marcel to override if SFCC-277's own grooming later says otherwise.
 *
 * **Placeholder body -- deliberately generic, no AU-specific contact details.** The real Figma
 * copy (session-notes.md §11.7) is "If you'd like some help, speak to one of our Client Services
 * Advisors at: / +61 1800 738 895 / Monday – Saturday: 9:00AM – 5:30PM / or
 * clientservices@zimmermann.com" -- hardcoded to the AU storefront in the design, with no AC
 * covering how it should vary across the other 7 storefronts / 6 regions. Marcel settled
 * (session-notes.md §11.9, 2026-09-16) that this is explicitly not this build's problem: "we ship
 * a placeholder empty state only; the real one is SFCC-277's... the question carries to SFCC-277
 * -- flag on 277 at grooming." The copy above echoes only the real line's opening phrase (which
 * names no region-specific detail) and invites contact with no number, hours, or email at all.
 *
 * **No outer vertical padding set.** There is no confirmed Figma value for the vertical space
 * around this block once nested in the drawer body, and `.claude/rules/overrideStyling.md`
 * ("Component-local tokens") is explicit for exactly this situation: "leave it inherited... rather
 * than inventing a number." (`recentlyViewed/index.tsx`'s own `EmptyRecentlyViewed` uses
 * `paddingY="var(--zimm-scale-4xl)"` here, but that value is itself disclosed in that file as an
 * unconfirmed autonomous guess -- reusing it would just be borrowing one unverified number into a
 * second, unrelated component rather than independently confirming it, which
 * `.claude/rules/typescript.md`-adjacent house discipline on reused numbers argues against.)
 * Horizontal gutter needs no equivalent decision: `ZimmCartDrawer`'s own `body` part already
 * applies `paddingInline` at every breakpoint (`zimmCartDrawer.css.ts`), so this component
 * inherits it once nested there rather than declaring a second, competing value.
 *
 * **Recipe (`zimmCartEmptyState.css.ts`) owns exactly one thing:** making this component's root
 * span both of `ZimmCartDrawer`'s desktop grid tracks (session-notes.md §11.7 / plan.md step 4.5:
 * "two columns collapse to one") instead of being confined to the 360px items column with 430px
 * of dead space beside it. See that file's own docblock for the full mechanism, and this step's
 * own report for how far that was verified live vs. deferred to step 4.6 (the container that
 * will actually nest this component inside the real drawer at zero items -- not built yet;
 * `ZimmCartDrawer` today still renders its own hardcoded interim placeholder text at
 * `itemCount === 0`, not `children`, so a real nested render of this component doesn't exist
 * until that step wires the swap).
 *
 * No props -- there is nothing for a caller to configure in a placeholder standing in for a card
 * that hasn't been groomed yet. SFCC-277 is expected to need real ones (at minimum, per-storefront
 * contact details) when it replaces this file's contents.
 */
export const ZimmCartEmptyState = () => {
  const intl = useIntl();
  const styles = useStyleConfig(ZIMM_CART_EMPTY_STATE_RECIPE);

  return (
    <chakra.div __css={styles} data-testid="zimm-cart-empty-state">
      <Center>
        <Stack spacing="var(--zimm-scale-xl)" textAlign="center">
          {/* var(--zimm-scale-xl) = 24px -- session-notes.md §11.10(4): "25px raw value --
              DECIDED (Marcel): implement 24px ... Applies to ... the empty-bag paragraph
              spacing." Same snap-to-nearest-token convention as
              zimmCartItemActions.css.ts's own `gap: 'var(--zimm-scale-xl)', // Figma: 25px,
              snapped to the nearest token (24px)` comment. */}
          <Text textStyle="body1" color="var(--zimm-color-text-default)">
            {intl.formatMessage(messages.body)}
          </Text>
          <Button as={Link} href="/" variant="primary" width={{ base: 'full', sm: 'auto' }} alignSelf="center">
            {intl.formatMessage(messages.continueShopping)}
          </Button>
        </Stack>
      </Center>
    </chakra.div>
  );
};

// --- Decision log -------------------------------------------------------------------------
// 1. No isRegistered branching (body copy or CTA) -- checked session-notes.md §§11.7/11.9/11.10
//    and SFCC-272's actual pulled AC text; none call for a split. See this file's own docblock
//    for the full reasoning. Ready for Marcel to override if SFCC-277's grooming disagrees.
// 2. CTA button included despite neither Figma (figma-reference/empty-bag.md) nor SFCC-272's AC
//    text showing/requesting one -- plan.md step 4.5's own "Changes" text mandates it via the
//    recentlyViewed/EmptyCart structural precedent. Disclosed, not silently assumed.
// 3. Body copy is generic placeholder prose, not the real Figma contact copy -- Marcel's own
//    2026-09-16 decision (session-notes.md §11.9), carried forward to SFCC-277's grooming.
// 4. No outer vertical padding -- no confirmed Figma value; left unset per
//    overrideStyling.md's "leave it inherited... rather than inventing a number," rather than
//    reusing recentlyViewed's own already-disclosed-as-unconfirmed 64px guess.
// 5. Text alignment (centred) is inherited from the mandated Box > Center > Stack precedent
//    structure, not independently confirmed against Figma (the empty-bag.md pull does not state
//    an alignment for the description text block either way).

