const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/@playwright/test');

const BASE = 'http://localhost:6006/iframe.html';

const STORIES = [
  { id: 'commerce-zimmcartemptystate--default', name: 'Default' },
  { id: 'commerce-zimmcartemptystate--at-non-au-site', name: 'AtNonAuSite' },
  {
    id: 'commerce-zimmcartemptystate--spans-both-drawer-columns-at-desktop',
    name: 'SpansBothDrawerColumnsAtDesktop',
  },
];

function nowMs() {
  return Date.now();
}

async function run() {
  const browser = await chromium.launch({ headless: true });
  const results = {};

  for (const story of STORIES) {
    const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
    const page = await context.newPage();

    const captured = [];
    const startTime = nowMs();

    page.on('console', (msg) => {
      captured.push({
        tMs: nowMs() - startTime,
        kind: 'console',
        type: msg.type(),
        text: msg.text(),
        location: msg.location(),
      });
    });
    page.on('pageerror', (err) => {
      captured.push({
        tMs: nowMs() - startTime,
        kind: 'pageerror',
        message: err.message,
        stack: err.stack,
      });
    });
    page.on('requestfailed', (req) => {
      captured.push({
        tMs: nowMs() - startTime,
        kind: 'requestfailed',
        url: req.url(),
        failure: req.failure() && req.failure().errorText,
      });
    });

    const url = `${BASE}?id=${story.id}&viewMode=story`;
    let navError = null;
    try {
      await page.goto(url, { waitUntil: 'load', timeout: 30000 });
    } catch (e) {
      navError = e.message;
    }

    // Sample early (~100ms after mount) in case a play function throws
    // asynchronously right after paint -- capture is continuous via listeners
    // above regardless, this is just a documented early checkpoint.
    await page.waitForTimeout(100);
    const earlyCaptureCount = captured.length;

    // Let play functions fully settle.
    await page.waitForTimeout(1200);

    const entry = {
      url,
      navError,
      earlyCaptureCountAt100ms: earlyCaptureCount,
      totalCaptured: captured.length,
      captured,
    };

    // Independent corroboration beyond console/pageerror: a Storybook play-function
    // assertion failure is caught internally by Storybook's PreviewWeb and rendered as an
    // in-iframe error overlay / render-state change -- it is not guaranteed to also surface
    // as a console.error or an uncaught pageerror. Probe the DOM/global state directly.
    try {
      entry.storybookInternalState = await page.evaluate(() => {
        const errorMessageEl = document.getElementById('error-message');
        const errorStackEl = document.getElementById('error-stack');
        let previewRenderStates = null;
        try {
          const preview = window.__STORYBOOK_PREVIEW__;
          if (preview && preview.storyRenders) {
            const renders = Array.isArray(preview.storyRenders)
              ? preview.storyRenders
              : Array.from(preview.storyRenders.values ? preview.storyRenders.values() : preview.storyRenders);
            previewRenderStates = renders.map((r) => ({
              id: r.id,
              phase: r.phase,
              storyId: r.story && r.story.id,
            }));
          }
        } catch (e) {
          previewRenderStates = `probe threw: ${e.message}`;
        }
        return {
          documentTitle: document.title,
          bodyClassName: document.body.className,
          hasErrorMessageEl: !!errorMessageEl,
          errorMessageText: errorMessageEl ? errorMessageEl.textContent : null,
          errorStackText: errorStackEl ? errorStackEl.textContent : null,
          hasStorybookPreviewGlobal: typeof window.__STORYBOOK_PREVIEW__ !== 'undefined',
          previewRenderStates,
          rootInnerHTMLLength: document.getElementById('storybook-root')
            ? document.getElementById('storybook-root').innerHTML.length
            : null,
        };
      });
    } catch (e) {
      entry.storybookInternalStateError = e.message;
    }

    // Step 3: independent DOM read of the CTA href for AtNonAuSite.
    if (story.name === 'AtNonAuSite') {
      try {
        const link = page.getByRole('link', { name: 'Continue Shopping' });
        const count = await link.count();
        entry.ctaLinkCount = count;
        if (count > 0) {
          entry.ctaHrefAttribute = await link.first().getAttribute('href');
          entry.ctaOuterHTML = await link.first().evaluate((el) => el.outerHTML);
        }
      } catch (e) {
        entry.ctaCheckError = e.message;
      }
    }

    // Step 4: independent bounding box read for the grid harness + empty-state root.
    if (story.name === 'SpansBothDrawerColumnsAtDesktop') {
      try {
        const viewportSize = page.viewportSize();
        entry.viewportSize = viewportSize;
        const harness = page.locator('[data-testid="grid-harness"]');
        const root = page.locator('[data-testid="zimm-cart-empty-state"]');
        entry.harnessCount = await harness.count();
        entry.rootCount = await root.count();
        entry.harnessBox = await harness.boundingBox();
        entry.rootBox = await root.boundingBox();
        // also grab via evaluate as a cross-check
        entry.evalRects = await page.evaluate(() => {
          const h = document.querySelector('[data-testid="grid-harness"]');
          const r = document.querySelector('[data-testid="zimm-cart-empty-state"]');
          return {
            harness: h ? h.getBoundingClientRect().toJSON() : null,
            root: r ? r.getBoundingClientRect().toJSON() : null,
            innerWidth: window.innerWidth,
          };
        });
      } catch (e) {
        entry.boxCheckError = e.message;
      }
    }

    results[story.name] = entry;
    await context.close();
  }

  await browser.close();
  console.log(JSON.stringify(results, null, 2));
}

run().catch((e) => {
  console.error('FATAL', e);
  process.exit(1);
});

