const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/@playwright/test');

async function run() {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();
  const url =
    'http://localhost:6006/iframe.html?id=commerce-zimmcartemptystate--spans-both-drawer-columns-at-desktop&viewMode=story';
  await page.goto(url, { waitUntil: 'load', timeout: 30000 });
  await page.waitForTimeout(1200);

  const styleInfo = await page.evaluate(() => {
    const root = document.querySelector('[data-testid="zimm-cart-empty-state"]');
    const harness = document.querySelector('[data-testid="grid-harness"]');
    const rootStyle = root ? getComputedStyle(root) : null;
    const harnessStyle = harness ? getComputedStyle(harness) : null;
    return {
      rootDisplay: rootStyle && rootStyle.display,
      rootGridColumn: rootStyle && rootStyle.gridColumn,
      rootGridColumnStart: rootStyle && rootStyle.gridColumnStart,
      rootGridColumnEnd: rootStyle && rootStyle.gridColumnEnd,
      harnessDisplay: harnessStyle && harnessStyle.display,
      harnessGridTemplateColumns: harnessStyle && harnessStyle.gridTemplateColumns,
      rootFontSizePx: getComputedStyle(document.documentElement).fontSize,
    };
  });
  console.log(JSON.stringify(styleInfo, null, 2));

  await browser.close();
}

run().catch((e) => {
  console.error('FATAL', e);
  process.exit(1);
});

